class Solution:
    def levelOrder(self, root: TreeNode) -> List[List[int]]:
        ret = []
        if root is None:
            return ret
        q = [root]
        i = 0
        while q:
            ret.append([])
            p = []
            for node in q:
                ret[i].append(node.val)
                if node.left is not None:
                    p.append(node.left)
                if node.right is not None:
                    p.append(node.right)
            q = p
            i += 1
        return ret
